    [InlineData(Denomination.Fifty, 0, 1, 1, 0, 50, 30)]
    [InlineData(Denomination.Twenty, 1, 0, 1, 0, 60, 0)]
    [InlineData(Denomination.Ten, 1, 1, 0, 70, 70, 0)]
    public void Depot_hors_cassette_bloquee_est_accepte(
