        Assert.Equal(AtmStatus.Ok, withdraw.Status);
        Assert.Equal(N(1, 0, 0), withdraw.Notes);
        Assert.Equal(Acc(0, 50), withdraw.Account);
        Assert.Equal(N(0, 0, 0), dispenser.Stock);
    }
}
